MERGE INTO dbo.DocumentCheckLists AS tgt USING (SELECT   (SELECT Id FROM dbo.DocumentTypes   WHERE [Key] = 'dt_application_fee_proof_of_payment') AS DocumentTypeId,  (SELECT Id FROM dbo.ReferenceTypes  WHERE [Key] = 'rt_upload_rcs') AS ReferenceTypeId, 1 AS IsActive, 0 AS IsDeleted) AS src ON tgt.DocumentTypeId = src.DocumentTypeId AND tgt.ReferenceTypeId = src.ReferenceTypeId WHEN MATCHED THEN UPDATE SET tgt.IsActive=src.IsActive, tgt.IsDeleted=src.IsDeleted WHEN NOT MATCHED BY TARGET THEN INSERT (DocumentTypeId,ReferenceTypeId,IsActive,IsDeleted)   VALUES (src.DocumentTypeId,src.ReferenceTypeId,src.IsActive,src.IsDeleted);
 
    COMMIT TRANSACTION;
    PRINT 'Master data sync completed successfully.';
END TRY
BEGIN CATCH
    ROLLBACK TRANSACTION;
